\set ON_ERROR_STOP on
SELECT public.report_test_assert(current_database()='moderation_test' OR current_setting('test.dm_disposable',true)='1','disposable listing-appeal database');
RESET ROLE;
SELECT set_config('test.mc.cover',(SELECT id::text FROM public.mc_threads WHERE book_id='book-1' AND deadline_enforced_at IS NOT NULL ORDER BY deadline_enforced_at DESC LIMIT 1),false);
SELECT public.report_test_assert(nullif(current_setting('test.mc.cover',true),'') IS NOT NULL,'listing appeal tests reuse the auto-unpublished cover conversation');
UPDATE auth.sessions SET created_at=clock_timestamp();
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000004';
SET request.jwt.claims='{"session_id":"10000000-0000-0000-0000-000000000004","aal":"aal1"}';
SET ROLE authenticated;
SELECT public.report_expect_error($q$SELECT public.mc_submit_listing_appeal(current_setting('test.mc.cover')::uuid,'Please restore this listing to the public Library.')$q$,'permission denied');
SELECT public.report_expect_error(format('SELECT public.mc_call(''submit_listing_appeal'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''body'',''Please restore this listing to the public Library.''))',current_setting('test.mc.cover')),'not available');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
SET request.jwt.claims='{"session_id":"10000000-0000-0000-0000-000000000003","aal":"aal1"}';
SET ROLE authenticated;
SELECT public.report_test_assert((SELECT count(*) FROM jsonb_array_elements(public.mc_call('my_inbox')->'listings') t WHERE t->>'id'=current_setting('test.mc.cover'))=1,'recipient sees the unpublished listing');
SELECT public.report_test_assert((public.mc_call('my_thread',jsonb_build_object('id',current_setting('test.mc.cover')))->>'deadlineEnforcedAt') IS NOT NULL,'recipient can open the unpublished conversation');
SELECT public.mc_call('submit_listing_appeal',jsonb_build_object('requestId','b1000000-0000-0000-0000-000000000001','threadId',current_setting('test.mc.cover'),'body','Please restore this listing. I can update the cover now.'));
SELECT public.mc_call('submit_listing_appeal',jsonb_build_object('requestId','b1000000-0000-0000-0000-000000000001','threadId',current_setting('test.mc.cover'),'body','Please restore this listing. I can update the cover now.'));
SELECT public.report_expect_error(format('SELECT public.mc_call(''submit_listing_appeal'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''body'',''Please restore this listing a second time today.''))',current_setting('test.mc.cover')),'already have an open appeal');
SELECT public.report_test_assert((public.mc_call('my_inbox')->'listings'->0->>'appealStatus')='pending','open listing appeal is shown to the recipient');
RESET ROLE;
SELECT public.report_test_assert((SELECT count(*) FROM public.mc_listing_appeals WHERE thread_id=current_setting('test.mc.cover')::uuid)=1,'listing appeal retries save once');
SELECT public.report_test_assert(NOT EXISTS(SELECT 1 FROM public.mc_audit WHERE action='Listing appeal submitted' AND (details ? 'body' OR details::text ILIKE '%update the cover%')),'listing appeal audit omits the ticket body');
SELECT set_config('test.mc.listing_appeal',(SELECT id::text FROM public.mc_listing_appeals WHERE thread_id=current_setting('test.mc.cover')::uuid),false);
SET ROLE authenticated;
SELECT public.report_expect_error(format('SELECT public.mc_call(''appeal_decision'',jsonb_build_object(''requestId'',gen_random_uuid(),''id'',%L,''version'',1,''decision'',''granted'',''body'',''The author cannot restore their own listing.''))',current_setting('test.mc.listing_appeal')),'staff verification');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
SELECT set_config('request.jwt.claims',jsonb_build_object('session_id','10000000-0000-0000-0000-000000000001','email','staff@example.test','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',extract(epoch FROM clock_timestamp()))))::text,false);
SET ROLE authenticated;
SELECT public.mc_call('start');
SELECT public.report_test_assert((SELECT count(*) FROM jsonb_array_elements(public.mc_call('appeals')->'items') t WHERE t->>'kind'='listing' AND t->>'id'=current_setting('test.mc.listing_appeal'))=1,'staff see the listing appeal ticket');
SELECT public.report_test_assert((public.mc_call('dashboard')->>'pendingAppeals')::int>=1,'dashboard counts listing appeals');
SELECT public.mc_call('appeal_decision',jsonb_build_object('requestId','b1000000-0000-0000-0000-000000000002','id',current_setting('test.mc.listing_appeal'),'version',1,'decision','granted','body','The cover concern is resolved. This book is restored to the Library.'));
RESET ROLE;
SELECT public.report_test_assert((SELECT visibility FROM public.mc_book_visibility WHERE book_id='book-1')='visible','granted listing appeal restores the library listing');
SELECT public.report_test_assert((SELECT count(*) FROM public.get_published_book('book-1'))=1,'public reading shows the restored book');
SELECT public.report_test_assert(EXISTS(SELECT 1 FROM public.library_catalog WHERE id='book-1'),'catalog shows the restored book');
SELECT public.report_test_assert((SELECT count(*) FROM public.books WHERE id='book-1')=1,'studio manuscript remains after a granted listing appeal');
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
SET request.jwt.claims='{"session_id":"10000000-0000-0000-0000-000000000003","aal":"aal1"}';
SET ROLE authenticated;
SELECT public.report_test_assert((SELECT count(*) FROM jsonb_array_elements(public.mc_call('my_inbox')->'listings') t WHERE t->>'id'=current_setting('test.mc.cover'))=0,'restored listings leave the appeal list');
SELECT public.report_expect_error(format('SELECT public.mc_call(''submit_listing_appeal'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''body'',''Please restore this listing again after it returned.''))',current_setting('test.mc.cover')),'already in the Library');
RESET ROLE;
CREATE TEMP TABLE listing_appeal_counts AS SELECT (SELECT count(*) FROM public.mc_listing_appeals) a,(SELECT count(*) FROM public.mc_audit WHERE action LIKE 'Listing appeal%') u;
\ir ../../../supabase/live-site/supabase-moderation-listing-appeals.sql
SELECT public.report_test_assert((SELECT count(*) FROM public.mc_listing_appeals)=(SELECT a FROM listing_appeal_counts),'rerun preserves listing appeals');
SELECT public.report_test_assert((SELECT count(*) FROM public.mc_audit WHERE action LIKE 'Listing appeal%')=(SELECT u FROM listing_appeal_counts),'rerun preserves listing appeal audit rows');
SELECT 'Live moderation listing-appeal tests passed';
